<template>
  <div class="fu-ep-content">
    <div v-for="cat in filteredData" :key="cat.id">
      <div class="fu-ep__cat-label">{{ cat.name }}</div>
      <div class="fu-ep__grid">
        <button
          v-for="emoji in cat.emojis"
          :key="emoji.id"
          class="fu-ep__emoji-btn"
          @click="$emit('select', emoji.skins[0].native)"
        >
          {{ emoji.skins[0].native }}
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from "vue";

const props = defineProps({
  filterCategory: { type: String, default: "" },
  searchQuery: { type: String, default: "" },
});

defineEmits(["select"]);

const allCategories = ref([]);

onMounted(async () => {
  const [{ default: data }, { init }] = await Promise.all([
    import("@emoji-mart/data"),
    import("emoji-mart"),
  ]);
  await init({ data });

  const emojiMap = data.emojis;
  allCategories.value = data.categories.map((cat) => ({
    id: cat.id,
    name: cat.id.charAt(0).toUpperCase() + cat.id.slice(1),
    emojis: cat.emojis.map((id) => emojiMap[id]).filter(Boolean),
  }));
});

const filteredData = computed(() => {
  let data = allCategories.value;

  // 1. Filter by Category (Footer icons)
  if (props.filterCategory) {
    data = data.filter((c) => c.id === props.filterCategory);
  }

  // 2. Filter by Search (Header input)
  if (props.searchQuery) {
    const q = props.searchQuery.toLowerCase();
    return [
      {
        id: "search",
        name: "Search Results",
        emojis: data
          .flatMap((c) => c.emojis)
          .filter(
            (e) => e.id.toLowerCase().includes(q) || e.name.toLowerCase().includes(q)
          )
          .slice(0, 50),
      },
    ];
  }

  return data;
});
</script>

