<template>
  <div
      ref="rootRef"
      class="fu-text-composer"
      :class="{ 'fu-text-composer--reply': isReply, 'fu-text-composer--field': isField }"
  >
    <FuAvatar
        v-if="!isField"
        :name="authorName"
        :src="authorAvatar"
        :size="isReply ? 'sm' : 'md'"
        class="fu-text-composer__avatar"
    />

    <Transition name="fu-text-composer" mode="out-in" @enter="onEnter">
      <div v-if="!isExpanded" key="collapsed" class="fu-text-composer__collapsed">
        <button type="button" class="fu-text-composer__trigger" @click="expand">
          <MessageCircle :size="16" />
          <span class="fu-text-composer__trigger-text">{{ collapsedPlaceholder }}</span>
          <kbd v-if="shortcut" class="fu-text-composer__kbd">C</kbd>
        </button>

        <FusionActionButton
            v-if="uploader"
            :icon="Paperclip"
            size="sm"
            variant="subtle"
            tooltip="Attach file"
            @click="attachFromCollapsed"
        />
        <FusionActionButton
            :icon="AtSign"
            size="sm"
            variant="subtle"
            tooltip="Mention"
            @click="mentionFromCollapsed"
        />
      </div>

      <div
          v-else
          key="expanded"
          ref="cardRef"
          class="fu-text-composer__card"
          :class="{
          'is-editing': isEditing,
          'is-dragging': isDragging,
          'fu-text-composer__card--note': isNote,
          'fu-text-composer__card--field': isField,
        }"
          @dragenter.prevent="onDragEnter"
          @dragover.prevent
          @dragleave="onDragLeave"
          @drop.prevent="onDropOnCard"
      >
        <div v-if="isEditing && !isField" class="fu-text-composer__editing">
          <SquarePen :size="14" />
          <span>Editing {{ isNote ? "note" : isReply ? "reply" : "comment" }}</span>
          <span class="fu-text-composer__editing-hint">Esc to cancel</span>
        </div>

        <EditorContent :editor="editor" class="fu-text-composer__editor" />

        <!-- Attachment chips -->
        <div v-if="attachments.length" class="fu-text-composer__files">
          <div
              v-for="file in attachments"
              :key="file.key"
              class="fu-text-composer__file"
              :class="`is-${file.status}`"
              :title="file.error || file.name"
          >
            <Loader2 v-if="file.status === 'uploading'" :size="14" class="fu-spin" />
            <AlertCircle v-else-if="file.status === 'error'" :size="14" />
            <FileIcon v-else :size="14" />
            <span class="fu-text-composer__file-name">{{ file.name }}</span>
            <span class="fu-text-composer__file-size">
              {{ file.status === "error" ? "Failed" : formatSize(file.size) }}
            </span>
            <button
                type="button"
                class="fu-text-composer__file-remove"
                aria-label="Remove file"
                @click="removeAttachment(file.key)"
            >
              <X :size="12" />
            </button>
          </div>
        </div>

        <div v-if="inlineUploads > 0" class="fu-text-composer__uploading">
          <Loader2 :size="14" class="fu-spin" />
          <span>Uploading image…</span>
        </div>

        <FuTextCommandPalette
            ref="paletteRef"
            class="fu-text-composer__palette"
            :style="paletteAnchorStyle"
            @close="paletteOpen = false"
        >
          <template #people>
            <FuPeopleTab
              :members="members"
              :loading="membersLoading"
              :error="membersError"
              :load="loadMembers"
              @select="onSelectMember"
            />
          </template>
        </FuTextCommandPalette>

        <div v-if="editor" class="fu-text-composer__toolbar">
          <div class="fu-text-composer__toolbar-left">
            <FusionActionButton
                v-for="action in formatActions"
                :key="action.tooltip"
                :icon="action.icon"
                size="sm"
                :variant="action.isActive() ? 'subtle' : 'ghost'"
                :tooltip="action.tooltip"
                @click="action.run()"
            />

            <FuPopover
                ref="linkPopoverRef"
                align="left"
                side="bottom"
                width="280px"
                @open="onLinkOpen"
            >
              <template #trigger>
                <FusionActionButton
                    :icon="Link2"
                    size="sm"
                    :variant="editor.isActive('link') ? 'subtle' : 'ghost'"
                    tooltip="Link"
                />
              </template>
              <div class="p-2">
                <FusionTextInput
                    v-model="linkUrl"
                    size="sm"
                    formWrapperWidth="100%"
                    placeholder="Paste a link, then press Enter"
                    @keydown.enter.prevent="applyLink"
                />
              </div>
            </FuPopover>

            <FuPopover
                ref="emojiPopoverRef"
                align="left"
                side="bottom"
                width="300px"
                maxHeight="360px"
                @open="emojiSearch = ''"
            >
              <template #trigger>
                <FusionActionButton :icon="SmilePlus" size="sm" variant="ghost" tooltip="Emoji" />
              </template>
              <template #header>
                <div class="p-2">
                  <FusionTextInput
                      v-model="emojiSearch"
                      size="sm"
                      formWrapperWidth="100%"
                      placeholder="Search emoji..."
                  >
                    <template #left><Search :size="14" /></template>
                  </FusionTextInput>
                </div>
              </template>
              <FuEmojipicker :search-query="emojiSearch" @select="insertEmoji" />
            </FuPopover>

            <FusionActionButton
                :icon="List"
                size="sm"
                :variant="editor.isActive('bulletList') ? 'subtle' : 'ghost'"
                tooltip="Bullet list"
                @click="editor.chain().focus().toggleBulletList().run()"
            />

            <FusionActionButton
                v-if="uploader && !isField"
                :icon="Paperclip"
                size="sm"
                variant="ghost"
                tooltip="Attach file"
                @click="pickAttachments"
            />

            <span class="fu-text-composer__divider" />

            <FuPopover ref="morePopoverRef" align="left" side="bottom" width="200px">
              <template #trigger>
                <FusionActionButton :icon="Ellipsis" size="sm" variant="ghost" tooltip="More" />
              </template>
              <div class="fu-text-composer__more">
                <FusionButton
                    v-for="action in moreActions"
                    :key="action.text"
                    :icon="action.icon"
                    :text="action.text"
                    variant="ghost"
                    size="sm"
                    @click="runMore(action)"
                />
              </div>
            </FuPopover>
          </div>

          <!-- As a form field the parent form saves; no buttons of its own -->
          <div v-if="!isField" class="fu-text-composer__toolbar-right">
            <span v-if="isBusy" class="fu-text-composer__hint">Uploading…</span>
            <span v-else class="fu-text-composer__hint">{{ modKey }}+Enter to {{ submitVerb }}</span>

            <template v-if="isEditing || isNote || isReply">
              <FusionButton text="Cancel" variant="outline" size="sm" @click="cancel" />
              <FusionButton
                  :text="isReply && !isEditing ? 'Reply' : 'Save'"
                  variant="solid"
                  size="sm"
                  :disabled="!canSubmit"
                  :loading="submitting"
                  @click="submit"
              />
            </template>
            <FusionActionButton
                v-else
                :icon="SendHorizonal"
                size="sm"
                variant="subtle"
                tooltip="Post comment"
                :disabled="!canSubmit"
                @click="submit"
            />
          </div>
        </div>
      </div>
    </Transition>

    <input
        ref="attachmentInputRef"
        type="file"
        multiple
        class="fu-text-composer__input"
        @change="onAttachmentInput"
    />
    <input
        ref="imageInputRef"
        type="file"
        accept="image/jpeg,image/png,image/gif,image/webp"
        multiple
        class="fu-text-composer__input"
        @change="onImageInput"
    />
  </div>
</template>

<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount, watch } from "vue";
import { useEditor, EditorContent } from "@tiptap/vue-3";
import { StarterKit } from "@tiptap/starter-kit";
import { Placeholder } from "@tiptap/extensions";
import { Mention } from "@tiptap/extension-mention";
import { Image } from "@tiptap/extension-image";
import FuTextCommandPalette from "./FuTextCommandPalette.vue";
import FuPeopleTab from "./FuPeopleTab.vue";
import {
  MessageCircle,
  Paperclip,
  AtSign,
  SmilePlus,
  Bold,
  Italic,
  Strikethrough,
  Underline,
  Link2,
  List,
  ListOrdered,
  TextQuote,
  Code,
  ImagePlus,
  RemoveFormatting,
  Ellipsis,
  Search,
  SendHorizonal,
  SquarePen,
  Loader2,
  AlertCircle,
  File as FileIcon,
  X,
} from "@lucide/vue";
import FuEmojipicker from "./FuEmojipicker.vue";

const MAX_ATTACHMENTS = 10;
const INLINE_IMAGE_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp"];

const props = defineProps({
  authorName: { type: String, default: "" },
  authorAvatar: { type: String, default: "" },
  collapsedPlaceholder: { type: String, default: "Leave a comment…" },
  placeholder: { type: String, default: "Leave a comment, or @mention a teammate…" },
  defaultExpanded: { type: Boolean, default: false },
  variant: {
    type: String,
    default: "comment",
    validator: (v) => ["comment", "note", "reply"].includes(v),
  },
  /**
   * (file: File, kind: 'inline'|'attachment') => Promise<{ id, name, size, mime_type, url }>
   * Without it, the composer is text-only.
   */
  uploader: { type: Function, default: null },
  // Global "C" to open the composer. Only one composer on a page should have it.
  shortcut: { type: Boolean, default: true },
  // Parent sets this while the save request is in flight.
  submitting: { type: Boolean, default: false },
  /**
   * "composer" — post box (notes, comments, replies): avatar, Save/Post buttons, shortcuts.
   * "field"    — rich-text form input used with v-model: no avatar or buttons, always open;
   *              the surrounding form saves it.
   */
  mode: {
    type: String,
    default: "composer",
    validator: (v) => ["composer", "field"].includes(v),
  },
  /** People who can be @mentioned: [{ id, name, avatar?, status? }]. Leave empty for no mentions. */
  members: { type: Array, default: () => [] },
  membersLoading: { type: Boolean, default: false },
  membersError: { type: Boolean, default: false },
  /** Called when the mention list opens, so the app can fetch members lazily. */
  loadMembers: { type: Function, default: null },
  // v-model in "field" mode (HTML). Plain text from older records is turned into paragraphs.
  modelValue: { type: String, default: "" },
});

/**
 * submit / save payload: { html, text, attachmentIds }
 * cancel: the user closed the composer (reply composers use it to hide themselves)
 * expand: the composer opened (click, shortcut, or edit())
 */
const emit = defineEmits(["submit", "save", "cancel", "expand", "update:modelValue"]);

const isNote = computed(() => props.variant === "note");
const isReply = computed(() => props.variant === "reply");
const isField = computed(() => props.mode === "field");
// ⌘ on Apple devices, Ctrl everywhere else. userAgentData where available
// (navigator.platform is deprecated), userAgent as the fallback.
const isApple = /mac|iphone|ipad|ipod/i.test(
    navigator.userAgentData?.platform || navigator.platform || navigator.userAgent || ""
);
const modKey = isApple ? "⌘" : "Ctrl";
const submitVerb = computed(() => (isEditing.value || isNote.value ? "save" : isReply.value ? "reply" : "post"));

const rootRef = ref(null);
const isExpanded = ref(props.defaultExpanded || isField.value);
const isEditing = ref(false);
let pendingEditContent = null;

// ── Files ──────────────────────────────────────────────────────
// attachments: { key, id?, name, size, status: 'uploading'|'done'|'error', error? }
const attachments = ref([]);
const inlineUploads = ref(0);
const attachmentInputRef = ref(null);
const imageInputRef = ref(null);
let pendingPicker = null;

const isBusy = computed(
    () => inlineUploads.value > 0 || attachments.value.some((f) => f.status === "uploading")
);
const doneAttachmentIds = computed(() =>
    attachments.value.filter((f) => f.status === "done").map((f) => f.id)
);
const hasContent = computed(() => {
  if (!editor.value) return false;
  return !editor.value.isEmpty || doneAttachmentIds.value.length > 0;
});
const canSubmit = computed(() => hasContent.value && !isBusy.value && !props.submitting);

let keySeq = 0;
const nextKey = () => `f${Date.now()}-${keySeq++}`;

function formatSize(bytes) {
  if (!bytes && bytes !== 0) return "";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function toast(message, type = "error") {
  FusionToast({ message, type, duration: 3500 });
}

function handleFiles(fileList, { forceAttachment = false } = {}) {
  const files = Array.from(fileList || []);
  if (!files.length) return false;
  if (!props.uploader) return false;

  files.forEach((file) => {
    const isImage = !forceAttachment && INLINE_IMAGE_TYPES.includes(file.type);
    if (isImage) uploadInline(file);
    else if (isField.value) toast("Only images can be added here.");
    else uploadAttachment(file);
  });
  return true;
}

async function uploadInline(file) {
  inlineUploads.value++;
  try {
    const uploaded = await props.uploader(file, "inline");
    editor.value
        ?.chain()
        .focus()
        .setImage({ src: uploaded.url, alt: uploaded.name, fileId: uploaded.id })
        .run();
  } catch (err) {
    toast(err.message || "Image upload failed.");
  } finally {
    inlineUploads.value--;
  }
}

async function uploadAttachment(file) {
  if (attachments.value.filter((f) => f.status !== "error").length >= MAX_ATTACHMENTS) {
    toast(`You can attach up to ${MAX_ATTACHMENTS} files.`);
    return;
  }

  const key = nextKey();
  attachments.value.push({ key, name: file.name, size: file.size, status: "uploading" });

  try {
    const uploaded = await props.uploader(file, "attachment");
    updateAttachment(key, { ...uploaded, status: "done" });
  } catch (err) {
    updateAttachment(key, { status: "error", error: err.message || "Upload failed." });
    toast(err.message || "Upload failed.");
  }
}

function updateAttachment(key, patch) {
  attachments.value = attachments.value.map((f) => (f.key === key ? { ...f, ...patch } : f));
}

function removeAttachment(key) {
  attachments.value = attachments.value.filter((f) => f.key !== key);
}

function pickAttachments() {
  attachmentInputRef.value?.click();
}

function pickImages() {
  imageInputRef.value?.click();
}

function onAttachmentInput(event) {
  handleFiles(event.target.files, { forceAttachment: true });
  event.target.value = "";
}

function onImageInput(event) {
  handleFiles(event.target.files);
  event.target.value = "";
}

function attachFromCollapsed() {
  pendingPicker = "attachment";
  expand();
}

// Drag & drop onto the card: images go inline, other files become attachments.
const isDragging = ref(false);
let dragDepth = 0;

function onDragEnter(event) {
  if (!props.uploader || !event.dataTransfer?.types?.includes("Files")) return;
  dragDepth++;
  isDragging.value = true;
}

function onDragLeave() {
  dragDepth = Math.max(0, dragDepth - 1);
  if (dragDepth === 0) isDragging.value = false;
}

function onDropOnCard(event) {
  dragDepth = 0;
  isDragging.value = false;
  handleFiles(event.dataTransfer?.files);
}

// ── Mentions ───────────────────────────────────────────────────
const paletteRef = ref(null);
const paletteOpen = ref(false);
let mentionRange = null;
let pendingMention = false;

const cardRef = ref(null);
const paletteAnchorStyle = ref({});

function anchorPaletteAt(pos) {
  const view = editor.value?.view;
  const card = cardRef.value;
  if (!view || !card) return;
  const caret = view.coordsAtPos(pos ?? editor.value.state.selection.from);
  const box = card.getBoundingClientRect();
  paletteAnchorStyle.value = {
    display: "flex",
    top: `${caret.bottom - box.top}px`,
    left: `${caret.left - box.left}px`,
  };
}

function openMentions(pos) {
  anchorPaletteAt(typeof pos === "number" ? pos : undefined);
  paletteOpen.value = true;
  nextTick(() => paletteRef.value?.open("people"));
}

function onSelectMember(member) {
  const range = mentionRange;
  mentionRange = null;
  paletteRef.value?.close();

  let command = chain();
  if (range) command = command.deleteRange(range);
  command
      .insertContent({ type: "mention", attrs: { id: member.id, label: member.name } })
      .insertContent(" ")
      .run();
}

function mentionFromCollapsed() {
  pendingMention = true;
  expand();
}

// ── Editor ─────────────────────────────────────────────────────

/** v-model value → editor HTML. HTML passes through; plain text becomes paragraphs. */
function toHtml(value) {
  if (!value) return "";
  if (/<[a-z][\s\S]*>/i.test(value)) return value;
  const escape = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return value
      .split(/\r?\n/)
      .map((line) => `<p>${escape(line)}</p>`)
      .join("");
}

// Images carry the workspace file id; the server rebuilds their src from it.
const DiscussionImage = Image.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      fileId: {
        default: null,
        parseHTML: (el) => el.getAttribute("data-file-id"),
        renderHTML: (attrs) => (attrs.fileId ? { "data-file-id": attrs.fileId } : {}),
      },
    };
  },
});

const editor = useEditor({
  content: toHtml(props.modelValue),
  onUpdate: ({ editor: ed }) => {
    if (isField.value) emit("update:modelValue", ed.isEmpty ? "" : ed.getHTML());
  },
  extensions: [
    StarterKit.configure({ link: { openOnClick: false } }),
    Placeholder.configure({ placeholder: props.placeholder }),
    DiscussionImage.configure({ inline: false, allowBase64: false }),
    Mention.configure({
      HTMLAttributes: { class: "mention" },
      suggestion: {
        char: "@",
        render: () => ({
          onStart(suggestion) {
            mentionRange = suggestion.range;
            openMentions(suggestion.range.from);
          },
          onUpdate(suggestion) {
            mentionRange = suggestion.range;
          },
          onExit() {
            mentionRange = null;
            paletteRef.value?.close();
          },
        }),
      },
    }),
  ],
  editorProps: {
    handlePaste(view, event) {
      const files = event.clipboardData?.files;
      if (files?.length && handleFiles(files)) {
        event.preventDefault();
        return true;
      }
      return false;
    },
    handleDrop(view, event) {
      const files = event.dataTransfer?.files;
      if (files?.length && handleFiles(files)) {
        event.preventDefault();
        dragDepth = 0;
        isDragging.value = false;
        return true;
      }
      return false;
    },
    handleKeyDown(view, event) {
      if (paletteOpen.value) {
        if (event.key === "Escape") {
          paletteRef.value?.close();
          return true;
        }
        return false;
      }

      if (isField.value) return false;

      if (event.key === "Escape") {
        cancel();
        return true;
      }

      if (event.key !== "Enter") return false;

      // Cmd+Enter (Mac) / Ctrl+Enter (Windows, Linux) posts — notes, comments and replies alike.
      // Plain Enter stays a new line, so lists and paragraphs work in the rich text.
      // Both modifiers are accepted everywhere; the hint shows the platform's own key.
      if (!(event.metaKey || event.ctrlKey)) return false;

      event.preventDefault();
      submit();
      return true;
    },
  },
});

watch(
    () => props.modelValue,
    (value) => {
      if (!isField.value || !editor.value) return;
      const next = toHtml(value);
      const current = editor.value.isEmpty ? "" : editor.value.getHTML();
      if (next !== current) editor.value.commands.setContent(next, { emitUpdate: false });
    }
);

const chain = () => editor.value.chain().focus();

const formatActions = [
  { icon: Bold, tooltip: "Bold", isActive: () => editor.value.isActive("bold"), run: () => chain().toggleBold().run() },
  { icon: Italic, tooltip: "Italic", isActive: () => editor.value.isActive("italic"), run: () => chain().toggleItalic().run() },
  { icon: Strikethrough, tooltip: "Strikethrough", isActive: () => editor.value.isActive("strike"), run: () => chain().toggleStrike().run() },
  { icon: Underline, tooltip: "Underline", isActive: () => editor.value.isActive("underline"), run: () => chain().toggleUnderline().run() },
];

const moreActions = computed(() => [
  { icon: ListOrdered, text: "Numbered list", run: () => chain().toggleOrderedList().run() },
  { icon: TextQuote, text: "Quote", run: () => chain().toggleBlockquote().run() },
  { icon: Code, text: "Inline code", run: () => chain().toggleCode().run() },
  ...(props.uploader ? [{ icon: ImagePlus, text: "Insert image", run: pickImages }] : []),
  ...(props.uploader && !isField.value ? [{ icon: Paperclip, text: "Attach file", run: pickAttachments }] : []),
  { icon: AtSign, text: "Mention", run: openMentions },
  { icon: RemoveFormatting, text: "Clear formatting", run: () => chain().unsetAllMarks().clearNodes().run() },
]);

const morePopoverRef = ref(null);

function runMore(action) {
  morePopoverRef.value?.close();
  action.run();
}

const linkPopoverRef = ref(null);
const linkUrl = ref("");

function onLinkOpen() {
  linkUrl.value = editor.value?.getAttributes("link").href || "";
}

function applyLink() {
  const url = linkUrl.value.trim();
  if (url) chain().extendMarkRange("link").setLink({ href: url }).run();
  else chain().extendMarkRange("link").unsetLink().run();
  linkPopoverRef.value?.close();
}

const emojiPopoverRef = ref(null);
const emojiSearch = ref("");

function insertEmoji(emoji) {
  chain().insertContent(emoji).run();
  emojiPopoverRef.value?.close();
}

// ── Open / edit / submit ───────────────────────────────────────

function expand() {
  isExpanded.value = true;
  emit("expand");
}

function onEnter() {
  if (!isExpanded.value) return;
  if (pendingEditContent !== null) {
    applyEdit(pendingEditContent);
    pendingEditContent = null;
  } else {
    nextTick(() => editor.value?.commands.focus("end"));
  }
  if (pendingMention) {
    pendingMention = false;
    nextTick(openMentions);
  }
  if (pendingPicker) {
    pendingPicker = null;
    nextTick(pickAttachments);
  }
}

function focus() {
  if (!isExpanded.value) return expand();
  nextTick(() => editor.value?.commands.focus("end"));
}

/**
 * Load an existing note/comment for editing.
 * @param {string} html
 * @param {Array<{id,name,size}>} files  its current attachments
 */
function edit(html, files = []) {
  isEditing.value = true;
  attachments.value = files.map((f) => ({ ...f, key: nextKey(), status: "done" }));
  if (isExpanded.value) {
    applyEdit(html);
  } else {
    pendingEditContent = html;
    expand();
  }
}

function applyEdit(html) {
  editor.value?.commands.setContent(html);
  nextTick(() => {
    editor.value?.commands.focus("end");
    rootRef.value?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  });
}

function submit() {
  if (!editor.value) return;
  if (isBusy.value) {
    toast("Wait for the uploads to finish.", "info");
    return;
  }
  if (!canSubmit.value) return;

  const payload = {
    html: editor.value.isEmpty ? "" : editor.value.getHTML(),
    text: editor.value.getText(),
    attachmentIds: doneAttachmentIds.value,
  };
  emit(isEditing.value ? "save" : "submit", payload);
}

function reset() {
  editor.value?.commands.clearContent();
  attachments.value = [];
  isEditing.value = false;
  isExpanded.value = props.defaultExpanded || isField.value;
}

function cancel() {
  reset();
  emit("cancel");
}

defineExpose({ focus, edit, reset });

// ── Global "C" shortcut ────────────────────────────────────────
function handleShortcut(event) {
  if (!props.shortcut || isField.value) return;
  if (isExpanded.value || event.metaKey || event.ctrlKey || event.altKey) return;
  if (event.key.toLowerCase() !== "c") return;
  const target = event.target;
  if (target?.isContentEditable || target?.closest?.("input, textarea, select")) return;
  event.preventDefault();
  expand();
}

onMounted(() => window.addEventListener("keydown", handleShortcut));
onBeforeUnmount(() => {
  window.removeEventListener("keydown", handleShortcut);
  editor.value?.destroy();
});
</script>

