<template>
  <nav class="fu-nav-shell" :style="shellStyle" aria-label="Main navigation">
    <!-- Tier 1: icon rail -->
    <div class="fu-nav-rail">
      <div class="fu-nav-rail__top">
        <slot name="logo">
          <img v-if="logoSrc" :src="logoSrc" :alt="logoAlt" class="fu-nav-rail__logo-img" />
          <div v-else class="fu-nav-rail__logo">{{ logoText }}</div>
        </slot>
        <span class="fu-nav-rail__sep" aria-hidden="true" />

        <button
          v-for="section in sections"
          :key="section.name"
          type="button"
          class="fu-nav-rail__btn"
          :class="{ 'is-active': section.name === currentName }"
          :aria-label="section.label"
          :aria-current="section.name === currentName ? 'true' : undefined"
          @mouseenter="showTip($event, section.label)"
          @mouseleave="hideTip"
          @focus="showTip($event, section.label)"
          @blur="hideTip"
          @click="hideTip(); selectSection(section)"
        >
          <component :is="section.icon" :size="20" />
          <span v-if="section.badge" class="fu-nav-rail__badge">{{ section.badge }}</span>
        </button>
      </div>

      <div class="fu-nav-rail__bottom">
        <button
          v-if="collapsible && isCollapsed"
          type="button"
          class="fu-nav-rail__btn"
          aria-label="Expand menu"
          @mouseenter="showTip($event, 'Expand menu')"
          @mouseleave="hideTip"
          @focus="showTip($event, 'Expand menu')"
          @blur="hideTip"
          @click="hideTip(); setCollapsed(false)"
        >
          <PanelLeftOpen :size="20" />
        </button>
        <button
          v-for="action in bottomActions"
          :key="action.name"
          type="button"
          class="fu-nav-rail__btn"
          :aria-label="action.label"
          @mouseenter="showTip($event, action.label)"
          @mouseleave="hideTip"
          @focus="showTip($event, action.label)"
          @blur="hideTip"
          @click="hideTip(); onAction(action)"
        >
          <component :is="action.icon" :size="20" />
        </button>
        <slot name="user" />
      </div>
    </div>

    <!-- Tier 2: panel for the active section -->
    <div
      class="fu-nav-panel"
      :class="{ 'is-collapsed': isCollapsed }"
      :aria-hidden="isCollapsed ? 'true' : undefined"
      :inert="isCollapsed"
    >
     <div class="fu-nav-panel__inner">
      <header v-if="current" class="fu-nav-panel__header">
        <slot name="panel-header" :section="current">
          <div class="fu-nav-panel__heading">
            <div class="fu-nav-panel__title">{{ current.title ?? current.label }}</div>
            <div v-if="current.summary" class="fu-nav-panel__summary">{{ current.summary }}</div>
          </div>
        </slot>
        <div class="fu-nav-panel__header-action">
          <slot name="panel-header-action" :section="current" />
          <button
            v-if="collapsible"
            type="button"
            class="fu-nav-panel__collapse"
            aria-label="Collapse menu"
            @mouseenter="showTip($event, 'Collapse menu', 'bottom')"
          @mouseleave="hideTip"
          @focus="showTip($event, 'Collapse menu', 'bottom')"
          @blur="hideTip"
            @click="hideTip(); setCollapsed(true)"
          >
            <PanelLeftClose :size="18" />
          </button>
        </div>
      </header>

      <div class="fu-nav-panel__body customScrollBar">
        <ul v-if="pinned.length" class="fu-nav-list">
          <li v-for="item in pinned" :key="item.path">
            <a
              class="fu-nav-item"
              :class="{ 'is-active': isActive(item) }"
              :href="item.path"
              @click="onItemClick($event, item)"
            >
              <component v-if="item.icon" :is="item.icon" :size="18" class="fu-nav-item__icon" />
              <span class="fu-nav-item__label">{{ item.label }}</span>
              <span v-if="hasCount(item)" class="fu-nav-item__count">{{ item.count }}</span>
            </a>
          </li>
        </ul>

        <slot name="search">
          <button
            v-if="searchable"
            type="button"
            class="fu-nav-search"
            @click="emit('search')"
          >
            <Search :size="16" class="fu-nav-search__icon" />
            <span class="fu-nav-search__text">{{ searchPlaceholder }}</span>
            <kbd v-if="searchShortcut" class="fu-nav-search__kbd">{{ searchShortcut }}</kbd>
          </button>
        </slot>

        <template v-for="(group, gi) in current?.groups ?? []" :key="gi">
          <div v-if="group.title" class="fu-nav-group">
            <span class="fu-nav-group__title">{{ group.title }}</span>
            <button
              v-if="group.action"
              type="button"
              class="fu-nav-group__action"
              :aria-label="group.action.label"
              @mouseenter="showTip($event, group.action.label, 'bottom')"
          @mouseleave="hideTip"
          @focus="showTip($event, group.action.label, 'bottom')"
          @blur="hideTip"
              @click="hideTip(); group.action.onClick?.()"
            >
              <component :is="group.action.icon" :size="16" />
            </button>
          </div>

          <ul class="fu-nav-list">
            <li v-for="item in group.items" :key="item.path">
              <a
                class="fu-nav-item"
                :class="{ 'is-active': isActive(item) }"
                :href="item.path"
                :aria-current="isActive(item) ? 'page' : undefined"
                @click="onItemClick($event, item)"
              >
                <component v-if="item.icon" :is="item.icon" :size="18" class="fu-nav-item__icon" />
                <span class="fu-nav-item__label">{{ item.label }}</span>
                <span v-if="hasCount(item)" class="fu-nav-item__count">{{ item.count }}</span>
              </a>
            </li>
          </ul>
        </template>

        <slot />
      </div>

      <footer v-if="footer || $slots.footer" class="fu-nav-panel__footer">
        <slot name="footer">{{ footer }}</slot>
      </footer>
     </div>
    </div>
  
    <!-- Tooltip: teleported to <body> so the scrolling rail can never clip it -->
    <Teleport to="body">
      <span
        v-if="tip"
        class="fu-nav-tooltip"
        :class="`fu-nav-tooltip--${tip.side}`"
        role="tooltip"
        :style="{ left: `${tip.x}px`, top: `${tip.y}px` }"
      >{{ tip.text }}</span>
    </Teleport>
  </nav>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch, type Component } from "vue";
import { PanelLeftClose, PanelLeftOpen, Search } from "@lucide/vue";

export interface SidebarShellLink {
  label: string;
  /** Used for the href and active-state matching, e.g. "/admin/users" */
  path: string;
  icon?: Component;
  /** Muted count shown at the end of the row, e.g. 756 */
  count?: number | string;
}

export interface SidebarShellGroup {
  /** Small heading above the group, e.g. "Customers" */
  title?: string;
  /** Optional icon button next to the heading (e.g. sort) */
  action?: { label: string; icon: Component; onClick?: () => void };
  items: SidebarShellLink[];
}

export interface SidebarShellSection {
  name: string;
  /** Tooltip / accessible name of the rail button */
  label: string;
  icon: Component;
  /** Small pill on the rail icon (e.g. open tickets) */
  badge?: number | string;
  /** Panel heading — defaults to `label` */
  title?: string;
  /** Muted line under the heading, e.g. "756 users · 654 workspaces" */
  summary?: string;
  groups?: SidebarShellGroup[];
}

export interface SidebarShellAction {
  name: string;
  label: string;
  icon: Component;
  onClick?: () => void;
}

const props = withDefaults(
  defineProps<{
    sections: SidebarShellSection[];
    /** Links shown at the top of every section's panel (e.g. Dashboard) */
    pinned?: SidebarShellLink[];
    /** Name of the active section. If omitted it is derived from `activePath`. */
    activeSection?: string;
    /** Current location path, used to highlight the active link */
    activePath?: string;
    /** Icon buttons at the bottom of the rail (search, settings…) */
    bottomActions?: SidebarShellAction[];
    /** Image for the logo at the top of the rail (e.g. your brand mark). Overridden by the `logo` slot. */
    logoSrc?: string;
    logoAlt?: string;
    /** Letter(s) shown in a tile when there is no `logoSrc` or `logo` slot */
    logoText?: string;
    searchable?: boolean;
    searchPlaceholder?: string;
    /** Hint shown in the search box. Cmd/Ctrl+K also emits `search` when set to "⌘K". */
    searchShortcut?: string;
    /** Small text at the bottom of the panel, e.g. "HQ v1.0.0" */
    footer?: string;
    /** Lets people hide the panel so only the icon rail stays. Use `v-model:collapsed` to control/persist it. */
    collapsible?: boolean;
    collapsed?: boolean;
    railWidth?: string;
    panelWidth?: string;
  }>(),
  {
    pinned: () => [],
    bottomActions: () => [],
    logoAlt: "Logo",
    logoText: "S",
    searchable: true,
    searchPlaceholder: "Search",
    searchShortcut: "⌘K",
    collapsible: true,
    collapsed: false,
    railWidth: "52px",
    panelWidth: "208px",
  },
);

const emit = defineEmits<{
  /** A rail section was clicked */
  (e: "select-section", section: SidebarShellSection): void;
  /** A panel link was clicked — navigate with your router here */
  (e: "navigate", item: SidebarShellLink): void;
  /** Search box clicked, or Cmd/Ctrl+K pressed */
  (e: "search"): void;
  (e: "update:collapsed", value: boolean): void;
}>();

const innerCollapsed = ref(props.collapsed);
watch(
  () => props.collapsed,
  (value) => (innerCollapsed.value = value),
);
const isCollapsed = computed(() => props.collapsible && innerCollapsed.value);

function setCollapsed(value: boolean) {
  innerCollapsed.value = value;
  emit("update:collapsed", value);
}

const shellStyle = computed(() => ({
  "--fu-nav-rail-width": props.railWidth,
  "--fu-nav-panel-width": props.panelWidth,
}));

// Link matches its own path or anything beneath it ("/a/b" matches "/a/b/12" but not "/a/bc")
function matches(path: string, link: string) {
  return path === link || path.startsWith(link.endsWith("/") ? link : `${link}/`);
}

function isActive(item: SidebarShellLink) {
  if (!props.activePath) return false;
  // Longest matching link wins so "/billing" isn't active while "/billing/plans" is
  const all = [...props.pinned, ...props.sections.flatMap((s) => (s.groups ?? []).flatMap((g) => g.items))];
  const best = all
    .filter((l) => matches(props.activePath!, l.path))
    .sort((a, b) => b.path.length - a.path.length)[0];
  return best?.path === item.path;
}

const picked = ref<string | null>(null);
watch(
  () => props.activePath,
  () => (picked.value = null),
);

const derivedName = computed(() => {
  if (!props.activePath) return undefined;
  return props.sections.find((s) =>
    (s.groups ?? []).some((g) => g.items.some((i) => matches(props.activePath!, i.path))),
  )?.name;
});

const currentName = computed(
  () => picked.value ?? props.activeSection ?? derivedName.value ?? props.sections[0]?.name,
);
const current = computed(() => props.sections.find((s) => s.name === currentName.value));

// Clicking a section opens its panel; clicking the already-open section folds the panel away
function selectSection(section: SidebarShellSection) {
  if (props.collapsible && !isCollapsed.value && section.name === currentName.value) {
    setCollapsed(true);
    return;
  }
  picked.value = section.name;
  if (isCollapsed.value) setCollapsed(false);
  emit("select-section", section);
}

function onItemClick(e: MouseEvent, item: SidebarShellLink) {
  // Let the browser handle ctrl/cmd/middle-click (open in new tab)
  if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
  e.preventDefault();
  emit("navigate", item);
}

function onAction(action: SidebarShellAction) {
  if (action.name === "search") emit("search");
  action.onClick?.();
}

function hasCount(item: SidebarShellLink) {
  return item.count !== undefined && item.count !== null && item.count !== "";
}

// The browser's own `title` is slow and unstyled, so the shell draws its own tooltip.
// Rail buttons show it to the right; the panel's small buttons show it below.
const tip = ref<{ text: string; side: "right" | "bottom"; x: number; y: number } | null>(null);
let tipTimer: ReturnType<typeof setTimeout> | undefined;

function showTip(e: Event, text?: string, side: "right" | "bottom" = "right") {
  if (!text) return;
  const el = e.currentTarget as HTMLElement;
  clearTimeout(tipTimer);
  tipTimer = setTimeout(() => {
    const r = el.getBoundingClientRect();
    tip.value =
      side === "right"
        ? { text, side, x: r.right + 8, y: r.top + r.height / 2 }
        : { text, side, x: r.left + r.width / 2, y: r.bottom + 8 };
  }, 150);
}

function hideTip() {
  clearTimeout(tipTimer);
  tip.value = null;
}

onMounted(() => window.addEventListener("scroll", hideTip, true));
onBeforeUnmount(() => {
  window.removeEventListener("scroll", hideTip, true);
  clearTimeout(tipTimer);
});

function onKeydown(e: KeyboardEvent) {
  if (props.searchable && props.searchShortcut === "⌘K" && (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
    e.preventDefault();
    emit("search");
  }
}

onMounted(() => window.addEventListener("keydown", onKeydown));
onBeforeUnmount(() => window.removeEventListener("keydown", onKeydown));
</script>

<style scoped lang="scss">
@use "./FusionSidebarShell.scss";
</style>
