<template>
  <div class="fu-people-tab">
    <div class="fu-people-tab__search">
      <FusionTextInput
        ref="searchInputRef"
        v-model="query"
        size="sm"
        formWrapperWidth="100%"
        placeholder="Search members..."
        @input="onInput"
        @keydown.down.prevent="moveDown"
        @keydown.up.prevent="moveUp"
        @keydown.enter.prevent="selectActive"
      >
        <template #left><Search :size="14" /></template>
      </FusionTextInput>
    </div>

    <div v-if="loading" class="fu-people-tab__state">
      <span class="text-sm text-muted">Loading...</span>
    </div>

    <div v-else-if="error" class="fu-people-tab__state">
      <span class="text-sm text-muted">Failed to load members</span>
    </div>

    <template v-else>
      <button
        v-for="(member, i) in filtered"
        :key="member.id"
        class="fu-people-tab__item"
        :class="{ 'is-active': i === activeIndex }"
        @click="emit('select', member)"
        @mouseenter="activeIndex = i"
      >
        <FuAvatar
          :name="member.name"
          :src="member.avatar"
          :status="member.status"
          size="sm"
        />
        <div class="fu-people-tab__info">
          <span class="fu-people-tab__name" v-html="highlight(member.name)" />
        </div>
      </button>

      <div v-if="filtered.length === 0" class="fu-people-tab__state">
        <span class="text-sm text-muted">No members found</span>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, nextTick } from "vue";
import { Search } from "@lucide/vue";

const props = defineProps({
  /** People who can be mentioned: [{ id, name, avatar?, status? }] */
  members: { type: Array, default: () => [] },
  loading: { type: Boolean, default: false },
  error: { type: Boolean, default: false },
  /** Called when the list opens, so the app can fetch members lazily */
  load: { type: Function, default: null },
});

const emit = defineEmits(["select"]);

const query = ref("");
const activeIndex = ref(0);
const searchInputRef = ref(null);

const filtered = computed(() => {
  if (!query.value) return props.members;
  const q = query.value.toLowerCase();
  return props.members.filter((m) => m.name?.toLowerCase().includes(q));
});

function onInput() {
  activeIndex.value = 0;
}

function moveDown() {
  if (activeIndex.value < filtered.value.length - 1) activeIndex.value++;
}

function moveUp() {
  if (activeIndex.value > 0) activeIndex.value--;
}

function selectActive() {
  const member = filtered.value[activeIndex.value];
  if (member) emit("select", member);
}

function highlight(name) {
  if (!query.value) return name;
  const escaped = query.value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return name.replace(
    new RegExp(`(${escaped})`, "gi"),
    '<mark class="fu-people-tab__highlight">$1</mark>'
  );
}

onMounted(async () => {
  await props.load?.();
  await nextTick();
  const el = searchInputRef.value?.$el?.querySelector("input");
  if (el) el.focus();
});
</script>

