<template>
  <FuPopover ref="popoverRef" align="left" side="bottom" width="240px">
    <template #trigger>
      <button type="button" class="dcf-trigger" :disabled="readOnly">
        <span v-if="value">{{ formatted }}</span>
        <template v-else>
          <component :is="fieldTypeDef('date').icon" :size="13" />
          <span>{{ placeholder || "Select a date" }}</span>
        </template>
      </button>
    </template>

    <FusionPlainDatePicker
      :modelValue="value || null"
      mode="single"
      variant="date"
      formWrapperWidth="240px"
      @update:modelValue="onPicked"
    />
  </FuPopover>
</template>

<script setup>
import { ref, computed } from "vue";
import { fieldTypeDef } from "./fieldTypes.js";
import FuPopover from "../../popover/FuPopover.vue";
import FusionPlainDatePicker from "../../datePicker/plainDate/FusionPlainDatePicker.vue";

const props = defineProps({
  value: { type: String, default: null },
  placeholder: { type: String, default: "" },
  readOnly: { type: Boolean, default: false },
});
const emit = defineEmits(["update:value"]);

const popoverRef = ref(null);

function formatDate(v) {
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return v;
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}
const formatted = computed(() => (props.value ? formatDate(props.value) : ""));

function onPicked(v) {
  emit("update:value", v);
  popoverRef.value?.close();
}
</script>

<style scoped lang="scss">
.dcf-trigger {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: rem-calc(4);
  border: none;
  background: transparent;
  font: inherit;
  color: inherit;
  cursor: pointer;
  padding: rem-calc(2) rem-calc(6);
  overflow: hidden;
  white-space: nowrap;
}
.dcf-trigger:disabled {
  cursor: default;
}
</style>
