<template>
  <div
    ref="triggerRef"
    class="fu-color-trigger"
    :class="[`fu-color-trigger--${size}`, { 'fu-color-trigger--bare': bare }]"
    :style="bare ? undefined : { backgroundColor: hexString }"
    role="button"
    tabindex="0"
    aria-haspopup="dialog"
    :aria-expanded="open"
    @mousedown="keepFocusOnPress"
    @click="togglePopover"
    @keydown.enter.prevent="togglePopover"
    @keydown.space.prevent="togglePopover"
  >
    <slot name="trigger" />
  </div>

  <Teleport to="body">
    <div
      v-if="open"
      ref="popoverRef"
      class="fu-color-popover"
      role="dialog"
      aria-label="Choose a colour"
      :style="popoverStyle"
      @mousedown="keepFocusOnPress"
    >
      <!-- Tabs -->
      <div class="fu-color-tabs" role="tablist">
        <button
          v-for="t in TABS"
          :key="t.key"
          type="button"
          role="tab"
          class="fu-color-tab"
          :class="{ 'is-active': tab === t.key }"
          :aria-selected="tab === t.key"
          @click="setTab(t.key)"
        >
          {{ t.label }}
        </button>
      </div>

      <!-- Custom -->
      <div v-if="tab === 'custom'" class="fu-color-custom">
        <div
          class="fu-saturation"
          :style="paletteStyle"
          role="slider"
          tabindex="0"
          aria-label="Saturation and brightness"
          :aria-valuetext="`Saturation ${Math.round(sat)} percent, brightness ${Math.round(val)} percent`"
          @pointerdown="onFieldDown"
          @pointermove="onFieldMove"
          @pointerup="onPointerEnd"
          @pointercancel="onPointerEnd"
          @keydown="onFieldKey"
        >
          <div class="fu-cursor" :style="{ left: sat + '%', top: 100 - val + '%', backgroundColor: hexString }" />
        </div>

        <div
          class="fu-hue"
          role="slider"
          tabindex="0"
          aria-label="Hue"
          aria-valuemin="0"
          aria-valuemax="360"
          :aria-valuenow="Math.round(hue)"
          @pointerdown="onHueDown"
          @pointermove="onHueMove"
          @pointerup="onPointerEnd"
          @pointercancel="onPointerEnd"
          @keydown="onHueKey"
        >
          <div class="fu-cursor fu-cursor--hue" :style="{ left: (hue / 360) * 100 + '%', backgroundColor: hueColor }" />
        </div>

        <div class="fu-controls">
          <div class="fu-preview" title="New colour on the left, the colour it started as on the right">
            <i :style="{ backgroundColor: hexString }" />
            <i :style="{ backgroundColor: startHex }" />
          </div>
          <input
            class="fu-output"
            :value="outputInput"
            spellcheck="false"
            autocomplete="off"
            aria-label="Colour value"
            placeholder="#RRGGBB or rgb(...)"
            @input="onOutputInput"
            @blur="onOutputBlur"
            @keydown="onOutputKeydown"
          />
          <button
            v-if="canPick"
            type="button"
            class="fu-icon-btn"
            title="Pick a colour from the screen"
            aria-label="Pick a colour from the screen"
            @click="pickFromScreen"
          >
            <Pipette :size="16" />
          </button>
        </div>

        <div v-if="contrast" class="fu-contrast" :class="`is-${contrast.level}`">
          <span>{{ contrast.level === "fail" ? "!" : "✓" }}</span>
          <span>{{ contrast.ratio }} : 1 · {{ contrast.label }}</span>
        </div>

        <template v-if="usedSwatches.length">
          <div class="fu-color-label">In this document</div>
          <div class="fu-swatches">
            <button
              v-for="c in usedSwatches"
              :key="c"
              type="button"
              class="fu-swatch"
              :class="{ 'is-on': isCurrent(c) }"
              :style="{ backgroundColor: c }"
              :title="c"
              :aria-label="c"
              @click="chooseSwatch(c)"
            />
          </div>
        </template>
      </div>

      <!-- Swatches -->
      <div v-else class="fu-color-swatches">
        <div class="fu-color-label fu-color-label--first">Palette</div>
        <div class="fu-swatch-grid">
          <button
            v-for="c in PALETTE"
            :key="c"
            type="button"
            class="fu-swatch"
            :class="{ 'is-on': isCurrent(c) }"
            :style="{ backgroundColor: c }"
            :title="c"
            :aria-label="c"
            @click="chooseSwatch(c)"
          />
        </div>

        <div class="fu-color-label">Neutrals</div>
        <div class="fu-swatches">
          <button
            v-for="c in NEUTRALS"
            :key="c"
            type="button"
            class="fu-swatch"
            :class="{ 'is-on': isCurrent(c) }"
            :style="{ backgroundColor: c }"
            :title="c"
            :aria-label="c"
            @click="chooseSwatch(c)"
          />
        </div>

        <template v-if="recent.length">
          <div class="fu-color-label">Recent</div>
          <div class="fu-swatches">
            <button
              v-for="c in recent"
              :key="c"
              type="button"
              class="fu-swatch"
              :class="{ 'is-on': isCurrent(c) }"
              :style="{ backgroundColor: c }"
              :title="c"
              :aria-label="c"
              @click="chooseSwatch(c)"
            />
          </div>
        </template>
      </div>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { ref, computed, watch, nextTick, onMounted, onBeforeUnmount } from "vue";
import { Pipette } from "@lucide/vue";

type PopoverStyle = { top: string; left: string; transformOrigin?: string };
type ColorFormat = "hex" | "rgb";
type Rgb = { r: number; g: number; b: number };

const props = defineProps<{
  modelValue?: string;
  size?: "xs" | "sm" | "md";
  /** Colours already used in the document, shown under the picker ("In this document") */
  swatches?: string[];
  /** A background colour: shows the contrast ratio of the chosen colour against it */
  contrastWith?: string;
  /** Show the screen eyedropper where the browser has one (Chrome, Edge). Default true */
  eyedropper?: boolean;
  /** No circle: the trigger slot is the whole button, so a host (a toolbar, say) draws its own */
  bare?: boolean;
  /** The page keeps its focus and text selection while the picker is used, so a colour can be applied to selected text */
  keepFocus?: boolean;
}>();

const emit = defineEmits<{
  (e: "update:modelValue", value: string): void;
}>();

const size = computed(() => props.size ?? "md");

/* ── Palettes ─────────────────────────────────────────── */
function hslToHex(h: number, s: number, l: number) {
  s /= 100;
  l /= 100;
  const k = (n: number) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
  const to = (v: number) => Math.round(v * 255).toString(16).padStart(2, "0");
  return `#${to(f(0))}${to(f(8))}${to(f(4))}`.toUpperCase();
}

// 8 hues, light to dark, one row per shade
const PALETTE = [
  [92, 85],
  [75, 70],
  [58, 70],
  [40, 70],
].flatMap(([l, s]) => [0, 25, 48, 100, 160, 200, 230, 275].map((h) => hslToHex(h, s, l)));

const NEUTRALS = ["#FFFFFF", "#F3F3F3", "#E2E2E2", "#9CA3AF", "#525252", "#171717", "#000000"];

const TABS = [
  { key: "custom", label: "Custom" },
  { key: "swatches", label: "Swatches" },
] as const;
const tab = ref<"custom" | "swatches">("custom");

/* ── Open / position ──────────────────────────────────── */
const open = ref(false);
const triggerRef = ref<HTMLElement | null>(null);
const popoverRef = ref<HTMLElement | null>(null);
const popoverStyle = ref<PopoverStyle>({ top: "0px", left: "0px" });

function togglePopover() {
  if (open.value) return close(false);
  startHex.value = hexString.value;
  tab.value = "custom";
  open.value = true;
  nextTick(() => {
    positionPopover();
    // Keyboard users land inside the picker (a mouse click shows no focus ring), unless the page must keep its focus
    if (!props.keepFocus) {
      popoverRef.value?.querySelector<HTMLElement>(".fu-color-tab.is-active")?.focus({ preventScroll: true });
    }
  });
}

// With keepFocus a press on the trigger or on the picker (except its text box) does not move the focus
function keepFocusOnPress(e: MouseEvent) {
  if (!props.keepFocus) return;
  if ((e.target as HTMLElement).closest?.("input, textarea")) return;
  e.preventDefault();
}

function close(refocus: boolean) {
  open.value = false;
  if (refocus) nextTick(() => triggerRef.value?.focus());
}

function setTab(key: "custom" | "swatches") {
  tab.value = key;
  nextTick(positionPopover);
}

// Fixed to the screen, so it stays beside its trigger even inside a side panel that scrolls
function positionPopover() {
  if (!triggerRef.value) return;
  const trigger = triggerRef.value.getBoundingClientRect();
  const el = popoverRef.value;
  const popoverWidth = el?.offsetWidth || 264;
  const popoverHeight = el?.offsetHeight || 340;
  const padding = 8;

  let top = trigger.bottom + 6;
  let left = trigger.left;
  let origin = "top left";

  if (left + popoverWidth > window.innerWidth - padding) {
    left = trigger.right - popoverWidth;
    origin = "top right";
  }
  left = Math.max(padding, left);

  if (top + popoverHeight > window.innerHeight - padding) {
    top = trigger.top - popoverHeight - 6;
    origin = origin.includes("right") ? "bottom right" : "bottom left";
  }
  top = Math.max(padding, top);

  popoverStyle.value = { top: `${top}px`, left: `${left}px`, transformOrigin: origin };
}

function onDocumentPointer(e: Event) {
  if (!open.value) return;
  const t = e.target as Node;
  if (triggerRef.value?.contains(t) || (t as HTMLElement).closest?.(".fu-color-popover")) return;
  close(false);
}

function onEscape(e: KeyboardEvent) {
  if (!open.value || e.key !== "Escape") return;
  e.stopPropagation();
  close(true);
}

function onViewportChange() {
  if (open.value) positionPopover();
}

onMounted(() => {
  window.addEventListener("pointerdown", onDocumentPointer);
  window.addEventListener("keydown", onEscape, true);
  window.addEventListener("resize", onViewportChange);
  window.addEventListener("scroll", onViewportChange, true);
  loadRecent();
  if (props.modelValue) syncFrom(props.modelValue);
});
onBeforeUnmount(() => {
  window.removeEventListener("pointerdown", onDocumentPointer);
  window.removeEventListener("keydown", onEscape, true);
  window.removeEventListener("resize", onViewportChange);
  window.removeEventListener("scroll", onViewportChange, true);
});

/* ── Colour model ─────────────────────────────────────── */
const format = ref<ColorFormat>("hex");
const hue = ref(0);
const sat = ref(100);
const val = ref(100);
const outputInput = ref("");
const startHex = ref("#000000");

function hsvToRgb(h: number, s: number, v: number): Rgb {
  s /= 100;
  v /= 100;
  const c = v * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - c;
  let r = 0,
    g = 0,
    b = 0;
  if (h < 60) [r, g, b] = [c, x, 0];
  else if (h < 120) [r, g, b] = [x, c, 0];
  else if (h < 180) [r, g, b] = [0, c, x];
  else if (h < 240) [r, g, b] = [0, x, c];
  else if (h < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return {
    r: Math.round((r + m) * 255),
    g: Math.round((g + m) * 255),
    b: Math.round((b + m) * 255),
  };
}

function rgbToHsv(r: number, g: number, b: number) {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b),
    min = Math.min(r, g, b),
    d = max - min;
  let h = 0;
  if (d) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  // Not rounded: a colour that is typed or clicked must come back as exactly the same colour
  return {
    h,
    s: (max === 0 ? 0 : d / max) * 100,
    v: max * 100,
  };
}

function rgbToHex(r: number, g: number, b: number) {
  return (
    "#" +
    [r, g, b]
      .map((v) => v.toString(16).padStart(2, "0"))
      .join("")
      .toUpperCase()
  );
}
const rgbToString = (r: number, g: number, b: number) => `rgb(${r}, ${g}, ${b})`;

/** "#abc", "#aabbcc" or "rgb(1, 2, 3)" -> { r, g, b }, or null when it is neither */
function parseColor(input: string): { rgb: Rgb; format: ColorFormat } | null {
  const v = input.trim().replace(/;$/, "");
  const short = v.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i);
  if (short) {
    return {
      format: "hex",
      rgb: { r: parseInt(short[1] + short[1], 16), g: parseInt(short[2] + short[2], 16), b: parseInt(short[3] + short[3], 16) },
    };
  }
  if (/^#([0-9a-f]{6})$/i.test(v)) {
    return {
      format: "hex",
      rgb: { r: parseInt(v.slice(1, 3), 16), g: parseInt(v.slice(3, 5), 16), b: parseInt(v.slice(5, 7), 16) },
    };
  }
  const m = v.match(/^rgba?\((\d{1,3}),\s*(\d{1,3}),\s*(\d{1,3})/i);
  if (m) {
    const clamp = (n: string) => Math.min(255, +n);
    return { format: "rgb", rgb: { r: clamp(m[1]), g: clamp(m[2]), b: clamp(m[3]) } };
  }
  return null;
}

const rgb = computed(() => hsvToRgb(hue.value, sat.value, val.value));
const hexString = computed(() => rgbToHex(rgb.value.r, rgb.value.g, rgb.value.b));
const hueColor = computed(() => {
  const c = hsvToRgb(hue.value, 100, 100);
  return rgbToHex(c.r, c.g, c.b);
});
const paletteStyle = computed(() => ({
  background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, hsl(${hue.value}, 100%, 50%))`,
}));

const formatted = () => {
  const { r, g, b } = rgb.value;
  return format.value === "rgb" ? rgbToString(r, g, b) : hexString.value;
};

function emitColor() {
  emit("update:modelValue", formatted());
}

/** Takes a colour from outside (the v-model, a swatch, the eyedropper, typing) into the picker */
function setFrom(value: string): boolean {
  const parsed = parseColor(value);
  if (!parsed) return false;
  format.value = parsed.format;
  const hsv = rgbToHsv(parsed.rgb.r, parsed.rgb.g, parsed.rgb.b);
  // A grey has no hue of its own: keep the one on screen so the slider does not jump to red
  if (hsv.s > 0 && hsv.v > 0) hue.value = hsv.h;
  sat.value = hsv.s;
  val.value = hsv.v;
  return true;
}

// The v-model changed from outside: follow it, and only answer back when the parent's text is not how we write it
function syncFrom(value: string) {
  if (!setFrom(value)) return;
  outputInput.value = value;
  if (formatted() !== value.trim()) emitColor();
}

watch(
  () => props.modelValue,
  (v) => {
    if (!v || v === formatted()) return;
    syncFrom(v);
  }
);

// The text box shows what the picker writes, unless the person is typing in it
const typing = ref(false);
watch([hue, sat, val, format], () => {
  if (!typing.value) outputInput.value = formatted();
});

/* ── Field and hue (pointer capture: the drag keeps going outside the box) ── */
function fieldFrom(e: PointerEvent) {
  const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
  sat.value = Math.round((Math.min(Math.max(0, e.clientX - r.left), r.width) / r.width) * 100);
  val.value = Math.round(100 - (Math.min(Math.max(0, e.clientY - r.top), r.height) / r.height) * 100);
  emitColor();
}
function onFieldDown(e: PointerEvent) {
  (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  fieldFrom(e);
}
function onFieldMove(e: PointerEvent) {
  if ((e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) fieldFrom(e);
}

function hueFrom(e: PointerEvent) {
  const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
  hue.value = Math.round((Math.min(Math.max(0, e.clientX - r.left), r.width) / r.width) * 360);
  emitColor();
}
function onHueDown(e: PointerEvent) {
  (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  hueFrom(e);
}
function onHueMove(e: PointerEvent) {
  if ((e.currentTarget as HTMLElement).hasPointerCapture(e.pointerId)) hueFrom(e);
}
function onPointerEnd(e: PointerEvent) {
  const el = e.currentTarget as HTMLElement;
  if (el.hasPointerCapture(e.pointerId)) el.releasePointerCapture(e.pointerId);
  remember(hexString.value);
}

// Arrow keys move the thumbs (hold Shift for bigger steps)
function onFieldKey(e: KeyboardEvent) {
  const step = e.shiftKey ? 10 : 1;
  const move: Record<string, () => void> = {
    ArrowLeft: () => (sat.value = Math.max(0, Math.round(sat.value) - step)),
    ArrowRight: () => (sat.value = Math.min(100, Math.round(sat.value) + step)),
    ArrowUp: () => (val.value = Math.min(100, Math.round(val.value) + step)),
    ArrowDown: () => (val.value = Math.max(0, Math.round(val.value) - step)),
  };
  if (!move[e.key]) return;
  e.preventDefault();
  move[e.key]();
  emitColor();
}
function onHueKey(e: KeyboardEvent) {
  const step = e.shiftKey ? 15 : 1;
  if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
  e.preventDefault();
  hue.value = Math.min(360, Math.max(0, Math.round(hue.value) + (e.key === "ArrowRight" ? step : -step)));
  emitColor();
}

/* ── Typing ───────────────────────────────────────────── */
function onOutputInput(e: Event) {
  typing.value = true;
  outputInput.value = (e.target as HTMLInputElement).value;
  // Follow a complete value while it is typed, so the preview is live
  if (parseColor(outputInput.value)) {
    setFrom(outputInput.value);
    emitColor();
  }
}
function onOutputBlur() {
  typing.value = false;
  if (setFrom(outputInput.value)) {
    emitColor();
    remember(hexString.value);
  }
  outputInput.value = formatted();
}
function onOutputKeydown(e: KeyboardEvent) {
  if (e.key === "Enter") onOutputBlur();
}

/* ── Swatches, recent colours, eyedropper ─────────────── */
const usedSwatches = computed(() => {
  const seen = new Set<string>();
  for (const c of props.swatches ?? []) {
    const p = typeof c === "string" ? parseColor(c) : null;
    if (p) seen.add(rgbToHex(p.rgb.r, p.rgb.g, p.rgb.b));
  }
  return [...seen].slice(0, 14);
});

const isCurrent = (c: string) => c.toUpperCase() === hexString.value;

function chooseSwatch(c: string) {
  setFrom(c);
  emitColor();
  remember(hexString.value);
}

const RECENT_KEY = "fu-color-recent";
const recent = ref<string[]>([]);
function loadRecent() {
  try {
    const stored = JSON.parse(localStorage.getItem(RECENT_KEY) || "[]");
    if (Array.isArray(stored)) recent.value = stored.filter((c) => typeof c === "string").slice(0, 8);
  } catch {
    recent.value = [];
  }
}
function remember(hex: string) {
  recent.value = [hex, ...recent.value.filter((c) => c !== hex)].slice(0, 8);
  try {
    localStorage.setItem(RECENT_KEY, JSON.stringify(recent.value));
  } catch {
    /* private mode: the list simply is not kept */
  }
}

const canPick = computed(
  () => props.eyedropper !== false && typeof window !== "undefined" && "EyeDropper" in window
);
async function pickFromScreen() {
  try {
    const result = await new (window as any).EyeDropper().open();
    if (result?.sRGBHex) chooseSwatch(result.sRGBHex);
  } catch {
    /* cancelled with Escape */
  }
}

/* ── Contrast (WCAG) ──────────────────────────────────── */
function luminance({ r, g, b }: Rgb) {
  const c = [r, g, b].map((v) => {
    v /= 255;
    return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
const contrast = computed(() => {
  const against = props.contrastWith ? parseColor(props.contrastWith) : null;
  if (!against) return null;
  const a = luminance(rgb.value);
  const b = luminance(against.rgb);
  const ratio = (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
  const level = ratio >= 7 ? "aaa" : ratio >= 4.5 ? "aa" : ratio >= 3 ? "large" : "fail";
  const label = { aaa: "AAA", aa: "AA", large: "Large text only", fail: "Too low to read" }[level];
  return { ratio: ratio.toFixed(1), level, label };
});
</script>

<style scoped lang="scss">
