.fu-color-trigger {
  border-radius: 50%;
  cursor: pointer;
  border: rem-calc(2) solid var(--fu-modal-surface, #fff);
  box-shadow: 0 0 0 rem-calc(1) color-mix(in srgb, var(--fu-color-text, #171717) 25%, transparent),
    0 rem-calc(2) rem-calc(6) color-mix(in srgb, var(--fu-color-text, #171717) 18%, transparent);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.fu-color-trigger:hover {
  transform: scale(1.05);
}
.fu-color-trigger:focus-visible {
  outline: none;
  box-shadow: 0 0 0 rem-calc(2) var(--fu-color-text, #171717);
}

/* ── Sizes ───────────────────────────────────────────── */
.fu-color-trigger--xs {
  width: rem-calc(16);
  height: rem-calc(16);
}
.fu-color-trigger--sm {
  width: rem-calc(22);
  height: rem-calc(22);
}
.fu-color-trigger--md {
  width: rem-calc(30);
  height: rem-calc(30);
}

/* Bare: no circle, no ring. The trigger slot draws the whole button. */
.fu-color-trigger--bare {
  width: auto;
  height: auto;
  border: 0;
  border-radius: 0;
  background: none;
  box-shadow: none;
}
.fu-color-trigger--bare:hover {
  transform: none;
}
.fu-color-trigger--bare:focus-visible {
  box-shadow: none;
  outline: rem-calc(2) solid var(--fu-color-text, #171717);
  outline-offset: rem-calc(2);
}

.fu-color-popover {
  --_ring: color-mix(in srgb, var(--fu-color-text, #171717) 14%, transparent);
  --_muted: var(--fu-label-text, #525252);
  --_control: var(--fu-form-control, #f3f3f3);
  position: fixed;
  z-index: 1000;
  width: rem-calc(264);
  box-sizing: border-box;
