<template>
  <component
    :is="clickable ? 'button' : 'div'"
    class="fu-info-card"
    :class="{ 'fu-info-card--clickable': clickable }"
    :type="clickable ? 'button' : undefined"
    @click="onClick"
  >
    <div class="fu-info-card__visual">
      <img
        v-if="image"
        :src="image"
        :alt="imageAlt || title"
        class="fu-info-card__image"
      />
      <div v-else class="fu-info-card__initial" :style="{ background: color }">
        {{ displayInitial }}
      </div>
    </div>

    <div class="fu-info-card__body">
      <span class="fu-info-card__title">{{ title }}</span>
      <span v-if="description" class="fu-info-card__description">{{ description }}</span>
    </div>

    <div v-if="$slots.actions" class="fu-info-card__actions" @click.stop>
      <slot name="actions" />
    </div>
  </component>
</template>

<script setup lang="ts">
import { computed } from "vue";

export interface FusionInfoCardProps {
  /** Main heading — also the source for the auto-derived initial when no `initial` is given */
  title: string;
  /** Supporting text shown under the title */
  description?: string;
  /** Image URL for the visual. When omitted, a colored initial square is shown instead */
  image?: string;
  imageAlt?: string;
  /** Overrides the auto-derived (first letter of `title`) initial shown when there's no `image` */
  initial?: string;
  /** Background color of the initial square */
  color?: string;
  /** Renders as a `<button>` with hover/focus affordance and emits `click` */
  clickable?: boolean;
}

const props = withDefaults(defineProps<FusionInfoCardProps>(), {
  color: "#2563eb",
  clickable: true,
});

const emit = defineEmits<{ (e: "click"): void }>();

const displayInitial = computed(() => {
  if (props.initial) return props.initial.slice(0, 2).toUpperCase();
  return props.title?.trim().charAt(0).toUpperCase() || "?";
});

function onClick() {
  if (props.clickable) emit("click");
}
</script>

