<template>
  <div class="fu-empty" :class="[`fu-empty--${size}`, `fu-empty--${variant}`]">
    <!-- Visual -->
    <div v-if="visual && visual.type !== 'none'" class="fu-empty__visual">
      <component
        v-if="visual.type === 'icon'"
        :is="visual.value"
        class="fu-empty__icon"
      />
      <img
        v-else-if="visual.type === 'image'"
        :src="visual.src"
        :alt="visual.alt"
        class="fu-empty__image"
      />
    </div>

    <!-- Text -->
    <div class="fu-empty__body">
      <p class="fu-empty__title">{{ title }}</p>
      <p v-if="description" class="fu-empty__description">{{ description }}</p>
    </div>

    <!-- Custom content — e.g. a details card or an info callout that doesn't
         fit the title/description/actions shape -->
    <div v-if="$slots.default" class="fu-empty__content">
      <slot />
    </div>

    <!-- Actions -->
    <div v-if="primaryAction || secondaryActions?.length" class="fu-empty__actions">
      <FusionButton
        v-if="primaryAction"
        :text="primaryAction.label"
        buttonWidth="fit-content"
        @click="primaryAction.onClick?.()"
      />
      <FusionButton
        v-for="action in secondaryActions"
        :key="action.label"
        :text="action.label"
        buttonWidth="fit-content"
        variant="subtle"
        @click="action.onClick?.()"
      />
    </div>

    <!-- Cards — e.g. a list of workspaces/items to pick from -->
    <div v-if="cards?.length" class="fu-empty__cards">
      <FusionInfoCard
        v-for="(card, index) in cards"
        :key="card.title + index"
        :title="card.title"
        :description="card.description"
        :image="card.image"
        :initial="card.initial"
        :color="card.color"
        @click="card.onClick?.()"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import type { Component } from "vue";
import FusionButton from "@/components/button/FusionButton.vue";
import FusionInfoCard from "@/components/cards/FusionInfoCard.vue";

interface Action {
  label: string;
  onClick?: () => void;
  href?: string;
}

interface EmptyCardItem {
  title: string;
  description?: string;
  image?: string;
  initial?: string;
  color?: string;
  onClick?: () => void;
}

interface EmptyStateProps {
  title: string;
  description?: string;
  visual?:
    | { type: "icon"; value: Component }
    | { type: "image"; src: string; alt: string }
    | { type: "none" };
  primaryAction?: Action;
  secondaryActions?: Action[];
  /** Optional list of picker cards rendered below the actions (see `FusionInfoCard`) */
  cards?: EmptyCardItem[];
  size?: "sm" | "md" | "lg";
  variant?: "default" | "subtle" | "minimal";
}

withDefaults(defineProps<EmptyStateProps>(), {
  size: "md",
  variant: "default",
});
</script>

