<template>
  <div class="fu-palette-anchor">
    <FuPopover
      ref="paletteRef"
      align="left"
      :side="side"
      width="340px"
      maxHeight="400px"
      @close="emit('close')"
    >
      <template #trigger>
        <slot name="trigger" />
      </template>

      <template v-if="tabs.length > 1" #header>
        <div class="fu-palette__tabs border-bottom-1">
          <button
            v-for="tab in tabs"
            :key="tab.id"
            class="fu-palette__tab"
            :class="{ 'is-active': activeTab === tab.id }"
            @click="activeTab = tab.id"
          >
            {{ tab.label }}
          </button>
        </div>
      </template>

      <template v-if="hint" #footer>
        <div class="p-2 mb-b">
          <span class="text-xxs text-muted">{{ hint }}</span>
        </div>
      </template>

      <div class="fu-palette__body">
        <slot :name="activeTab" :query="internalQuery" />
      </div>
    </FuPopover>
  </div>
</template>

<script setup>
import { ref, computed } from "vue";

const props = defineProps({
  tabs: { type: Array, default: () => [{ id: "people", label: "People" }] },
  defaultTab: { type: String, default: "people" },
  hint: { type: String, default: "" },
  side: { type: String, default: "bottom" },
  query: { type: String, default: "" },
});

const emit = defineEmits(["close"]);

const paletteRef = ref(null);
const activeTab = ref(props.defaultTab);
const internalQuery = ref(props.query);

const tabIds = computed(() => props.tabs.map((t) => t.id));

function open(tab) {
  if (tab) activeTab.value = tab;
  paletteRef.value?.open();
}

function close() {
  paletteRef.value?.close();
}

function setQuery(q) {
  internalQuery.value = q;
}

function cycleTab() {
  const current = tabIds.value.indexOf(activeTab.value);
  activeTab.value = tabIds.value[(current + 1) % tabIds.value.length];
}

function cycleTabBack() {
  const current = tabIds.value.indexOf(activeTab.value);
  activeTab.value = tabIds.value[(current - 1 + tabIds.value.length) % tabIds.value.length];
}

defineExpose({ open, close, setQuery, cycleTab, cycleTabBack });
</script>

